import { getStoreDomain } from "../Utilities/UtilitiesFunctions";

const domain = getStoreDomain();
export const url = {
	home: () => `/${domain}`,

	catalog: () => `/${domain}/products`,

	category: (category) => `/${domain}/catalog/${category.slug}`,

	product: (product) => `/${domain}/${product?.name}`,
};

export function getCategoryParents(category) {
	return category.parent
		? [...getCategoryParents(category.parent), category.parent]
		: [];
}
